def index(root: Path, config: dict, *, rebuild: bool = False) -> dict:
    import sqlite_vec

    if rebuild:
        path = db_path(root, config)
        if path.exists():
            path.unlink()
    db = connect(root, config)
    try:
        known = {row["path"]: row for row in db.execute("SELECT id, path, hash FROM documents")}
        seen = set()
        changed = []
        for path in markdown_paths(root):
            relative = path.relative_to(root).as_posix()
            doc = parse(path, root)
            if doc is None:
                continue
            seen.add(relative)
            if relative not in known or known[relative]["hash"] != doc["hash"]:
                changed.append(doc)
        count_chunks = 0
        for doc in changed:
            meta = doc["metadata"]
            doc_chunks = chunks(doc["body"])
            texts = [f"{meta['title']}\n{chunk}" for chunk in doc_chunks]
            vectors = embed(texts, config)
            old = known.get(doc["path"])
            with db:
                if old and old["id"] != meta["id"]:
                    _delete_vectors(db, old["id"])
                    db.execute("DELETE FROM documents WHERE id=?", (old["id"],))
                _delete_vectors(db, meta["id"])
                db.execute("DELETE FROM chunks WHERE document_id=?", (meta["id"],))
                db.execute(
                    "INSERT INTO documents(id,path,hash,type,title,tags,importance,status,created_at,updated_at,body) "
                    "VALUES(?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET "
